package br.com.admeclesial.interfaces.web.usuario;
import br.com.admeclesial.application.usuario.*; import br.com.admeclesial.domain.usuario.PerfilAcesso; import br.com.admeclesial.infrastructure.persistence.pessoa.PessoaRepository; import br.com.admeclesial.infrastructure.persistence.organizacao.OrganizacaoEclesialRepository; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import java.util.*;
@Controller @RequestMapping("/usuarios") public class UsuarioWebController { private final UsuarioApplicationService service; private final PessoaRepository pessoas; private final OrganizacaoEclesialRepository orgs; public UsuarioWebController(UsuarioApplicationService s,PessoaRepository p,OrganizacaoEclesialRepository o){service=s;pessoas=p;orgs=o;} @GetMapping String lista(Model m){m.addAttribute("usuarios",service.listar());return "usuario/lista";} @GetMapping("/novo") String novo(Model m){base(m);return "usuario/form";} @PostMapping String criar(@RequestParam UUID pessoaUuid,@RequestParam String login,@RequestParam String senha,@RequestParam(defaultValue="true") boolean ativo,@RequestParam Set<PerfilAcesso> perfis,@RequestParam Set<UUID> organizacoes){service.criar(new UsuarioRequest(pessoaUuid,login,senha,ativo,perfis,organizacoes));return "redirect:/usuarios";} private void base(Model m){m.addAttribute("pessoas",pessoas.findAllByOrderByNomeAsc());m.addAttribute("organizacoes",orgs.findAllByOrderByNomeAsc());m.addAttribute("perfis",PerfilAcesso.values());} }
